#include <stdio.h>
int main(void) {
    int n;
    scanf("%d", n); /* & is missing */
    printf("%d\n", n);
    return 0;
}

#include <stdio.h>
void f(void) {
    static int x = 0;
    x++;
    printf("%d ", x);
}
int main(void) {
    f();
    f();
    f();
    printf("\n");
    return 0;
}

